/**
 * Deterministic policy document parsing: text layer, registry, first adapter.
 *
 * NO NETWORK, NO DB, NO MODEL CALL. Every PDF here is SYNTHETIC, generated by
 * fixtures/policyDocs/generate.mjs from template.mjs. Expected values are
 * written out by hand from that template, never taken from the parser.
 * The OCR tests run the real local OCR engine on image-only pages.
 *
 * Run:  npx tsx --test backend/server/tests/policyDocParser.test.ts
 */

import { test, describe, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { parsePolicyDocument } from "../services/policyDocs";
import { acquireText, DocumentReadError, LIMITS } from "../services/policyDocs/textLayer";
import { identifyAndParse, register, registeredAdapters, type PolicyAdapter } from "../services/policyDocs/registry";
import { tesseractOcr, shutdownOcr } from "../services/policyDocs/ocr";

const here = path.dirname(fileURLToPath(import.meta.url));
const fx = (f: string) => new Uint8Array(fs.readFileSync(path.join(here, "fixtures/policyDocs", f)));
after(async () => { await shutdownOcr(); });

